<?php
namespace App\Http\Controllers\Storefront;
use App\Http\Controllers\Controller; use App\Models\{Product,Category,Brand,Vendor}; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class SearchSuggestionController extends Controller { public function __invoke(Request $request):JsonResponse { $q=trim((string)$request->query('q','')); if(mb_strlen($q)<2)return response()->json(['products'=>[],'categories'=>[],'brands'=>[],'stores'=>[]]); $q=mb_substr($q,0,120); $like='%'.addcslashes($q,'%_\\').'%'; return response()->json(['products'=>Product::publiclyVisible()->where('name','like',$like)->with('primaryImage')->limit(5)->get(['id','name','slug'])->map(fn($p)=>['name'=>$p->name,'url'=>route('storefront.products.show',$p->slug),'image'=>$p->primaryImage?->url])->values(),'categories'=>Category::active()->where('name','like',$like)->limit(3)->get(['name','slug'])->map(fn($c)=>['name'=>$c->name,'url'=>route('storefront.categories.show',$c->slug)]),'brands'=>Brand::active()->where('name','like',$like)->limit(3)->get(['name','slug'])->map(fn($b)=>['name'=>$b->name,'url'=>route('storefront.brands.show',$b->slug)]),'stores'=>Vendor::approved()->where('display_name','like',$like)->limit(3)->get(['display_name','slug'])->map(fn($v)=>['name'=>$v->display_name,'url'=>route('storefront.stores.show',$v->slug)])]); } }
